"""Authentication: registration, login and current user."""

from __future__ import annotations

import re

from fastapi import APIRouter, Depends, status
from pydantic import BaseModel, Field
from sqlite3 import Connection

from app.config import Settings, get_settings
from app.db import get_db, utc_now
from app.errors import bad_request, conflict, unauthorized
from app.security import (
    CurrentUser,
    create_access_token,
    get_current_user,
    hash_password,
    password_problem,
    verify_password,
)

router = APIRouter(prefix="/api/auth", tags=["auth"])

USERNAME_RE = re.compile(r"^[A-Za-z0-9_-]{3,32}$")

class RegisterRequest(BaseModel):
    username: str = Field(..., min_length=3, max_length=32)
    password: str = Field(..., min_length=8)

class RegisterResponse(BaseModel):
    id: int
    username: str
    created_at: str

class LoginRequest(BaseModel):
    username: str
    password: str

class LoginResponse(BaseModel):
    access_token: str
    token_type: str = "bearer"
    expires_in: int

class MeResponse(BaseModel):
    id: int
    username: str
    created_at: str

@router.post(
    "/register",
    response_model=RegisterResponse,
    status_code=status.HTTP_201_CREATED,
    summary="Create a new account",
)
def register(
    data: RegisterRequest,
    conn: Connection = Depends(get_db),
    settings: Settings = Depends(get_settings),
) -> RegisterResponse:
    username = data.username.strip()
    password = data.password

    if not USERNAME_RE.fullmatch(username):
        raise bad_request("invalid_username", "Username must be 3-32 characters: letters, digits, _ or -.")

    problem = password_problem(password)
    if problem:
        raise bad_request("weak_password", problem)

    existing = conn.execute("SELECT id FROM users WHERE username = ? COLLATE NOCASE", (username,)).fetchone()
    if existing:
        raise conflict("username_taken", "This username is already taken.")

    password_hash = hash_password(password)
    created_at = utc_now()
    cur = conn.execute(
        "INSERT INTO users (username, password_hash, created_at) VALUES (?, ?, ?)",
        (username, password_hash, created_at),
    )
    user_id = cur.lastrowid
    assert user_id is not None

    return RegisterResponse(id=user_id, username=username, created_at=created_at)

@router.post("/login", response_model=LoginResponse, summary="Sign in and get an access token")
def login(
    data: LoginRequest,
    conn: Connection = Depends(get_db),
    settings: Settings = Depends(get_settings),
) -> LoginResponse:
    username = data.username.strip()
    password = data.password

    row = conn.execute("SELECT id, username, password_hash FROM users WHERE username = ? COLLATE NOCASE", (username,)).fetchone()

    if row and verify_password(password, row["password_hash"]):
        token = create_access_token(row["id"], row["username"], settings)
        audit(conn, "login", user_id=row["id"])
        return LoginResponse(access_token=token, expires_in=settings.token_ttl)

    audit(conn, "login_failed", detail=f"username={username}")
    raise unauthorized("invalid_credentials", "Invalid username or password.")

@router.get("/me", response_model=MeResponse, summary="Current user")
def me(current: CurrentUser = Depends(get_current_user), conn: Connection = Depends(get_db)) -> MeResponse:
    row = conn.execute("SELECT id, username, created_at FROM users WHERE id = ?", (current.id,)).fetchone()
    if not row:
        raise unauthorized("user_not_found", "User no longer exists.")
    return MeResponse(id=row["id"], username=row["username"], created_at=row["created_at"])
