from __future__ import annotations

from fastapi import APIRouter, Depends, Query, status
from pydantic import BaseModel, Field
from sqlite3 import Connection
from typing import Sequence

from app.config import Settings, get_settings
from app.db import get_db, utc_now, row_to_dict
from app.errors import not_found
from app.pagination import PageParams, page_params, paginate
from app.security import CurrentUser, get_current_user

router = APIRouter(prefix="/api/todos", tags=["todos"])

class TodoCreate(BaseModel):
    title: str = Field(..., min_length=1, max_length=200)

class TodoUpdate(BaseModel):
    title: str | None = Field(default=None, min_length=1, max_length=200)
    done: bool | None = None

class TodoResponse(BaseModel):
    id: int
    title: str
    done: bool
    created_at: str
    updated_at: str

class TodoListResponse(BaseModel):
    items: list[TodoResponse]
    total: int
    limit: int
    offset: int

def _todo_to_response(row: dict) -> TodoResponse:
    return TodoResponse(
        id=row["id"],
        title=row["title"],
        done=bool(row["done"]),
        created_at=row["created_at"],
        updated_at=row["updated_at"],
    )

@router.get("", response_model=TodoListResponse, summary="List todos")
def list_todos(
    done: bool | None = Query(default=None, description="Filter by done status"),
    page: PageParams = Depends(page_params),
    current: CurrentUser = Depends(get_current_user),
    conn: Connection = Depends(get_db),
) -> TodoListResponse:
    where = ["user_id = ?"]
    params: list = [current.id]
    if done is not None:
        where.append("done = ?")
        params.append(1 if done else 0)
    where_sql = " AND ".join(where)

    total_row = conn.execute(f"SELECT COUNT(*) FROM todos WHERE {where_sql}", params).fetchone()
    total = total_row[0] if total_row else 0

    rows = conn.execute(
        f"SELECT id, title, done, created_at, updated_at FROM todos WHERE {where_sql} ORDER BY created_at DESC LIMIT ? OFFSET ?",
        (*params, page.limit, page.offset),
    ).fetchall()

    items = [_todo_to_response(dict(row)) for row in rows]
    return TodoListResponse(items=items, total=total, limit=page.limit, offset=page.offset)

@router.post("", response_model=TodoResponse, status_code=status.HTTP_201_CREATED, summary="Create a todo")
def create_todo(
    data: TodoCreate,
    current: CurrentUser = Depends(get_current_user),
    conn: Connection = Depends(get_db),
) -> TodoResponse:
    title = data.title.strip()
    now = utc_now()
    cur = conn.execute(
        "INSERT INTO todos (user_id, title, done, created_at, updated_at) VALUES (?, ?, 0, ?, ?)",
        (current.id, title, now, now),
    )
    todo_id = cur.lastrowid
    assert todo_id is not None
    row = conn.execute(
        "SELECT id, title, done, created_at, updated_at FROM todos WHERE id = ?", (todo_id,)
    ).fetchone()
    assert row is not None
    return _todo_to_response(dict(row))

@router.get("/{todo_id}", response_model=TodoResponse, summary="Get a todo")
def get_todo(
    todo_id: int,
    current: CurrentUser = Depends(get_current_user),
    conn: Connection = Depends(get_db),
) -> TodoResponse:
    row = conn.execute(
        "SELECT id, title, done, created_at, updated_at FROM todos WHERE id = ? AND user_id = ?",
        (todo_id, current.id),
    ).fetchone()
    if not row:
        raise not_found("todo_not_found", "Todo not found.")
    return _todo_to_response(dict(row))

@router.patch("/{todo_id}", response_model=TodoResponse, summary="Update a todo")
def update_todo(
    todo_id: int,
    data: TodoUpdate,
    current: CurrentUser = Depends(get_current_user),
    conn: Connection = Depends(get_db),
) -> TodoResponse:
    row = conn.execute(
        "SELECT id, title, done, created_at, updated_at FROM todos WHERE id = ? AND user_id = ?",
        (todo_id, current.id),
    ).fetchone()
    if not row:
        raise not_found("todo_not_found", "Todo not found.")

    title = data.title.strip() if data.title is not None else row["title"]
    done = data.done if data.done is not None else row["done"]
    now = utc_now()

    conn.execute(
        "UPDATE todos SET title = ?, done = ?, updated_at = ? WHERE id = ?",
        (title, 1 if done else 0, now, todo_id),
    )

    updated = conn.execute(
        "SELECT id, title, done, created_at, updated_at FROM todos WHERE id = ?", (todo_id,)
    ).fetchone()
    assert updated is not None
    return _todo_to_response(dict(updated))

@router.delete("/{todo_id}", status_code=status.HTTP_204_NO_CONTENT, summary="Delete a todo")
def delete_todo(
    todo_id: int,
    current: CurrentUser = Depends(get_current_user),
    conn: Connection = Depends(get_db),
) -> None:
    cur = conn.execute(
        "DELETE FROM todos WHERE id = ? AND user_id = ?", (todo_id, current.id)
    )
    if cur.rowcount == 0:
        raise not_found("todo_not_found", "Todo not found.")
