import { apiFetch, ApiError } from "./api.js";
import { saveToken, clearToken, isSignedIn } from "./api.js";
import { el, clear, showMessage, formValues, whileBusy } from "./ui.js";

const loginForm = document.getElementById("login-form");
const registerForm = document.getElementById("register-form");
const loginSection = document.getElementById("login-form-section");
const registerSection = document.getElementById("register-form-section");
const showRegister = document.getElementById("show-register");
const showLogin = document.getElementById("show-login");

if (isSignedIn()) {
  location.href = "todos.html";
}

showRegister.addEventListener("click", (e) => {
  e.preventDefault();
  loginSection.hidden = true;
  registerSection.hidden = false;
  clear(document.getElementById("message"));
});

showLogin.addEventListener("click", (e) => {
  e.preventDefault();
  registerSection.hidden = true;
  loginSection.hidden = false;
  clear(document.getElementById("message"));
});

loginForm.addEventListener("submit", async (e) => {
  e.preventDefault();
  await whileBusy(loginForm, async () => {
    const data = formValues(loginForm);
    try {
      const resp = await apiFetch("/api/auth/login", {
        method: "POST",
        body: data,
      });
      saveToken(resp.access_token);
      location.href = "todos.html";
    } catch (err) {
      if (err instanceof ApiError) {
        showMessage(err.message, "error");
      } else {
        showMessage("An unexpected error occurred.", "error");
      }
    }
  });
