    await apiFetch(`/api/todos/${id}`, {
      method: "PATCH",
      body: { done },
    });
    showMessage(done ? "Marked as done." : "Marked as open.", "success");
  } catch (err) {
    if (err instanceof ApiError && err.status === 401) {
      clearToken();
      location.href = "login.html";
    } else {
      showMessage(err instanceof ApiError ? err.message : "Failed to update todo.", "error");
      loadTodos();
    }
  }
}

async function renameTodo(id, titleSpan) {
  const currentTitle = titleSpan.textContent;
  const input = el("input", { type: "text", value: currentTitle, maxlength: "200" });
  titleSpan.replaceWith(input);
  input.focus();
  input.select();

  const finish = async (save) => {
    if (save) {
      const newTitle = input.value.trim();
      if (newTitle && newTitle !== currentTitle) {
        try {
          await apiFetch(`/api/todos/${id}`, {
            method: "PATCH",
            body: { title: newTitle },
          });
          showMessage("Todo renamed.", "success");
        } catch (err) {
          if (err instanceof ApiError && err.status === 401) {
            clearToken();
            location.href = "login.html";
            return;
          }
          showMessage(err instanceof ApiError ? err.message : "Failed to rename todo.", "error");
        }
      }
    }
    const newSpan = el("span", { class: "title grow" }, save ? input.value.trim() || currentTitle : currentTitle);
    newSpan.addEventListener("dblclick", () => renameTodo(id, newSpan));
    input.replaceWith(newSpan);
  };

  input.addEventListener("blur", () => finish(true));
  input.addEventListener("keydown", (e) => {
    if (e.key === "Enter") finish(true);
    if (e.key === "Escape") finish(false);
  });
}

async function deleteTodo(id) {
  if (!confirm("Delete this todo?")) return;
  try {
    await apiFetch(`/api/todos/${id}`, { method: "DELETE" });
    showMessage("Todo deleted.", "success");
    loadTodos();
  } catch (err) {
    if (err instanceof ApiError && err.status === 401) {
      clearToken();
      location.href = "login.html";
    } else {
      showMessage(err instanceof ApiError ? err.message : "Failed to delete todo.", "error");
    }
  }
}

addForm.addEventListener("submit", async (e) => {
  e.preventDefault();
  await whileBusy(addForm, async () => {
    const data = formValues(addForm);
    try {
      await apiFetch("/api/todos", {
        method: "POST",
        body: data,
      });
      addForm.reset();
      showMessage("Todo added.", "success");
      currentOffset = 0;
      loadTodos();
    } catch (err) {
      if (err instanceof ApiError && err.status === 401) {
        clearToken();
        location.href = "login.html";
      } else {
        showMessage(err instanceof ApiError ? err.message : "Failed to add todo.", "error");
      }
    }
  });
});

prevBtn.addEventListener("click", () => {
  if (currentOffset > 0) {
    currentOffset -= PAGE_SIZE;
    loadTodos();
  }
});

nextBtn.addEventListener("click", () => {
  if (currentOffset + PAGE_SIZE < totalItems) {
    currentOffset += PAGE_SIZE;
    loadTodos();
  }
});

for (const radio of filterRadios) {
